/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountFloatingUiHero, type FloatingUiHeroOptions } from "../../components/floating-ui-hero/FloatingUiHeroEngine.js";
import type { MotionController } from "../../components/floating-ui-hero/motion-runtime";

export function FloatingUiHero({ options, className }: { options?: FloatingUiHeroOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountFloatingUiHero(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="floating-ui-hero" />;
}

